INSERT INTO `msg_r` (`id`, `user_from`, `user_to`, `time`, `read`, `mail_msg`) VALUES
(1, 'KraToS', 'Unknown', '01:59 18.01.15', 0, 'Добро пожаловать в игру Lineage 3!\nЭтот мир ждёт тебя, путешествуй, сражайся и просто отдыхай!\nТебе в помощь дали доспех и оружие, лучше одень их сразу в  <a href="inventar.php">инвентаре</a>! \nВопросы задавать в <a href="chat.php">чате</a>! Администрация на вопросы по игре не отвечает! \nПисать только насчёт найденых багов, недочётов и с предложениями! Рекомендуем ознакомится с <a href="faq.php">библиотекой</a> игры!\nПриятного времяпровождения!\n'),
(2, 'KraToS', 'Marvel', '02:05 18.01.15', 0, 'Добро пожаловать в игру Lineage 3!\nЭтот мир ждёт тебя, путешествуй, сражайся и просто отдыхай!\nТебе в помощь дали доспех и оружие, лучше одень их сразу в  <a href="inventar.php">инвентаре</a>! \nВопросы задавать в <a href="chat.php">чате</a>! Администрация на вопросы по игре не отвечает! \nПисать только насчёт найденых багов, недочётов и с предложениями! Рекомендуем ознакомится с <a href="faq.php">библиотекой</a> игры!\nПриятного времяпровождения!\n'),
(3, 'Система', 'KraToS', '03:04:50 | 18.01.2015', 1, 'Пытался зайти в адм панель '),
(4, 'Система', 'KraToS', '03:04:54 | 1421543094', 1, 'Пытался зайти в гм панель '),
(5, 'Система', 'KraToS', '03:04:55 | 18.01.2015', 1, 'Пытался зайти в адм панель '),
(6, 'Система', 'KraToS', '03:05:49 | 18.01.2015', 1, 'Пытался зайти в адм панель '),
